// SetTypingThrottleInterval configures the minimum interval between typing
// signals per session. Mattermost bots cannot emit typing events, so this is
// retained for interface parity with other transports.
func (a *Adapter) SetTypingThrottleInterval(interval time.Duration) {
	if a == nil {
		return
	}
	a.typingMu.Lock()
	defer a.typingMu.Unlock()
	a.typingThrottleInterval = interval
}

func(client *mattermost.Client, logger zerolog.Logger) *mattermost.Adapter {
	adapter := mattermost.NewAdapter(client, logger)
	// Mattermost bots cannot emit typing events, so the throttle only
	// keeps the shared progress-sugar path from doing pointless work.
	adapter.SetTypingThrottleInterval(5 * time.Second)
	return adapter
},

